begin;
select no_plan();
insert into auth.users(id,email) select ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'grocery-consent-'||i||'@example.test' from generate_series(5401,5404) i;
insert into public.profiles(id,name,age,sex,height_cm,weight_kg,units,experience,equipment,days_per_week,session_minutes,goal)
select id,'Consent '||right(id::text,4),30,'female',165,65,'metric','beginner',array['none'],3,30,'maintain' from auth.users where email like 'grocery-consent-%@example.test';
insert into public.grocery_lists(app_id,user_id,week_of,total_amount_centavos) values('consent-history','00000000-0000-0000-0000-000000005401','2026-10-25',100);
create temp table consent_state(name text primary key,value jsonb);
grant all on consent_state to authenticated;
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000005401';
select throws_ok($$select public.cooking_group_command('{"action":"invite","idempotencyKey":"consent-old-invite"}')$$,'P0001',null,'old invite requires refresh');
reset role;
select is((select count(*)::int from public.cooking_group_members where user_id='00000000-0000-0000-0000-000000005401'),0,'failed invite creates no membership');
select is((select count(*)::int from private.grocery_sharing where user_id='00000000-0000-0000-0000-000000005401'),0,'failed invite creates no consent');
set local role authenticated;
insert into consent_state values('invite',public.cooking_group_command('{"action":"invite","grocerySharingAcknowledgment":"all-weeks-v1","idempotencyKey":"consent-invite"}'));
select is(public.get_grocery_sharing_status()->>'status','transferring','PIN action records inviter consent');
reset role;
select is((select count(*)::int from private.grocery_transfers where user_id='00000000-0000-0000-0000-000000005401'),0,'PIN action does not transfer historical weeks');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000005402';
select public.cooking_group_command(jsonb_build_object('action','inspect-pin','pin',(select value->>'pin' from consent_state where name='invite')));
select throws_ok($$select public.cooking_group_command(jsonb_build_object('action','join','pin',(select value->>'pin' from consent_state where name='invite'),'groupRevision',1,'idempotencyKey','consent-old-join'))$$,'P0001',null,'old join requires refresh');
select throws_ok($$select public.cooking_group_command('{"action":"join","grocerySharingAcknowledgment":"all-weeks-v1","pin":"NOPE00","groupRevision":1,"idempotencyKey":"consent-invalid"}')$$,'P0001',null,'invalid connection fails');
reset role;
select is((select count(*)::int from private.grocery_sharing where user_id='00000000-0000-0000-0000-000000005402'),0,'failed joins create no consent');
set local role authenticated;
insert into consent_state values('joined',public.cooking_group_command(jsonb_build_object('action','join','grocerySharingAcknowledgment','all-weeks-v1','pin',(select value->>'pin' from consent_state where name='invite'),'groupRevision',1,'idempotencyKey','consent-join')));
select is(public.get_grocery_sharing_status()->>'status','enabled','successful join records recipient consent');
select is(public.cooking_group_command(jsonb_build_object('action','join','grocerySharingAcknowledgment','all-weeks-v1','pin',(select value->>'pin' from consent_state where name='invite'),'groupRevision',1,'idempotencyKey','consent-join'))->>'success','true','lost join response replays');
reset role;
-- Simulate a membership created before grocery consent was introduced.
delete from private.grocery_sharing where user_id in ('00000000-0000-0000-0000-000000005401','00000000-0000-0000-0000-000000005402');
set local role authenticated;
select is(public.get_grocery_sharing_status()->>'promptDismissed','false','legacy recipient prompt initially unacknowledged');
select public.share_cooking_groceries(jsonb_build_object('action','dismiss-grocery-sharing','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'userId','00000000-0000-0000-0000-000000005401','idempotencyKey','dismiss-recipient'));
select is(public.get_grocery_sharing_status()->>'promptDismissed','true','recipient dismissal persists');
select is(public.get_grocery_sharing_status()->>'status','not-enabled','dismissal never grants consent');
select lives_ok($$select public.share_cooking_groceries(jsonb_build_object('action','dismiss-grocery-sharing','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'userId','00000000-0000-0000-0000-000000005401','idempotencyKey','dismiss-recipient'))$$,'dismissal retries replay');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000005401';
select is(public.get_grocery_sharing_status()->>'promptDismissed','false','spoofed owner does not dismiss another member prompt');
select throws_ok($$select public.share_cooking_groceries(jsonb_build_object('action','dismiss-grocery-sharing','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',1,'idempotencyKey','dismiss-stale'))$$,'P0001',null,'dismissal validates reviewed group revision');
select public.share_cooking_groceries(jsonb_build_object('action','dismiss-grocery-sharing','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'idempotencyKey','dismiss-inviter'));
select public.share_cooking_groceries(jsonb_build_object('action','share-groceries','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'acknowledged',true,'idempotencyKey','settings-reopen'));
select is(public.get_grocery_sharing_status()->>'status','transferring','Settings review can accept after dismissal');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000005403';
select throws_ok($$select public.share_cooking_groceries(jsonb_build_object('action','dismiss-grocery-sharing','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'idempotencyKey','dismiss-outsider'))$$,'P0001',null,'non-members cannot dismiss group prompts');
reset role;
select ok((select relrowsecurity from pg_class where oid='private.grocery_sharing_prompt_dismissals'::regclass),'dismissal table has RLS');
select ok(not has_table_privilege('authenticated','private.grocery_sharing_prompt_dismissals','SELECT,INSERT,UPDATE,DELETE'),'no client access to private prompt records');
set local role anon;
select throws_ok($$select public.share_cooking_groceries('{}')$$,'42501',null,'anonymous mutations denied');
reset role;
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000005402';
select public.cooking_group_command(jsonb_build_object('action','leave','groupId',(select value->'group'->>'id' from consent_state where name='joined'),'groupRevision',2,'idempotencyKey','dismissal-leave'));
reset role;
select is((select count(*)::int from private.grocery_sharing_prompt_dismissals where user_id='00000000-0000-0000-0000-000000005402'),0,'departure clears membership-scoped dismissal');
select * from finish();
rollback;
